lean_proof:
intro hinj
let p : ℝ × ℝ := (1, 0)
let q : ℝ × ℝ := (-1, 0)
have hout : (fun z : ℝ × ℝ => (z.1^2-z.2^2, 2*z.1*z.2)) p = (fun z : ℝ × ℝ => (z.1^2-z.2^2, 2*z.1*z.2)) q := by norm_num [p, q]
have hne : p ≠ q := by norm_num [p, q]
exact hne (hinj hout)

intro hall
let f : ℝ → ℝ := fun _ => (1 : ℝ)
let g : ℝ → ℝ := fun _ => (0 : ℝ)
let h : ℝ → ℝ := fun _ => (0 : ℝ)
have heq := hall f g h
have hpoint := congrFun heq (0 : ℝ)
norm_num [f, g, h] at hpoint

intro h
let A : Set Bool := {true}
let B : Set Bool := {false}
let C : Set Bool := {false}
let D : Set Bool := {true}
have heq := h Bool Bool A C B D
have hp : (true, true) ∈ (A ∪ C) ×ˢ (B ∪ D) := by
  simp [A, B, C, D]
have hn : (true, true) ∉ (A ×ˢ B) ∪ (C ×ˢ D) := by
  simp [A, B, C, D]
apply hn
rw [heq]
exact hp

intro h
let A : Set Bool := {false}
let B : Set Bool := {false}
let C : Set Bool := {true}
let D : Set Bool := {true}
let p : Bool × Bool := (false, true)
have hEq := h Bool Bool A C B D
have hmem : p ∈ (A ∪ C) ×ˢ (B ∪ D) := by
  simp [A, B, C, D, p]
have hnmem : p ∉ (A ×ˢ B) ∪ (C ×ˢ D) := by
  simp [A, B, C, D, p]
rw [← hEq] at hmem
exact hnmem hmem
